/*! Tabler - Premium and Open Source dashboard template - Theme switcher */
(function(){const Tabler={setTheme:function(t){const e=document.documentElement;e.setAttribute("data-bs-theme",t),localStorage.setItem("tabler-theme",t)},getTheme:function(){return localStorage.getItem("tabler-theme")||"light"},initTheme:function(){const t=this.getTheme();this.setTheme(t)}};window.Tabler=Tabler,document.addEventListener("DOMContentLoaded",function(){Tabler.initTheme()})})();
